package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.junit.jupiter.api.*;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableGlobalMethodSecurity;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.AuthorityUtils;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.access.AccessDeniedException;import org.icu.sepsis.application.Store;
class SpecialtySecurityTest {
 @Configuration @EnableGlobalMethodSecurity(prePostEnabled=true) static class Security {}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void nurseCannotWriteClinicalSpecialtyEvidence(){try(var ctx=new AnnotationConfigApplicationContext()){var store=mock(Store.class);var svc=mock(SpecialtyEvidenceService.class);ctx.registerBean(Store.class,()->store);ctx.registerBean(DeteriorationService.class,()->mock(DeteriorationService.class));ctx.registerBean(ReviewedLabEvidenceService.class,()->mock(ReviewedLabEvidenceService.class));ctx.registerBean(SpecialtyEvidenceService.class,()->svc);ctx.registerBean(DataQualityService.class,()->mock(DataQualityService.class));ctx.registerBean(RenalMedicationReviewService.class,()->mock(RenalMedicationReviewService.class));ctx.register(Security.class,DeteriorationController.class);ctx.refresh();var actor=new UsernamePasswordAuthenticationToken("nurse","",AuthorityUtils.createAuthorityList("ROLE_NURSE"));SecurityContextHolder.getContext().setAuthentication(actor);assertThrows(AccessDeniedException.class,()->ctx.getBean(DeteriorationController.class).specialty("p","aki",new SpecialtyEvidenceService.Request(),actor));assertThrows(AccessDeniedException.class,()->ctx.getBean(DeteriorationController.class).medications("p"));verifyNoInteractions(store,svc);}}
}
